3	import { BrowserRouter, Route, Routes } from "react-router-dom";
4	import { Toaster as Sonner } from "@/components/ui/sonner";
5	import { Toaster } from "@/components/ui/toaster";
6	import { TooltipProvider } from "@/components/ui/tooltip";
7	import { AuthProvider } from "@/contexts/AuthContext";
8	import { ProtectedRoute } from "@/components/ProtectedRoute";
9	import { AdminRoute } from "@/components/AdminRoute";
10	import { AppLayout } from "@/components/AppLayout";
11	import Dashboard from "@/pages/Dashboard";
12	import Scan from "@/pages/Scan";
13	import Reports from "@/pages/Reports";
14	import AuditReport from "@/pages/AuditReport";
15	import Integrations from "@/pages/Integrations";
16	import SettingsPage from "@/pages/Settings";
17	import Pricing from "@/pages/Pricing";
18	import Landing from "@/pages/Landing";
19	import Login from "@/pages/Login";
20	import Signup from "@/pages/Signup";
21	import AuthCallback from "@/pages/AuthCallback";
22	import ForgotPassword from "@/pages/ForgotPassword";
23	import ResetPassword from "@/pages/ResetPassword";
24	import AgentHub from "@/pages/AgentHub";
25	import AgentWorkspace from "@/pages/AgentWorkspace";
26	import Privacy from "@/pages/Privacy";
27	import Terms from "@/pages/Terms";
28	import NotFound from "@/pages/NotFound";
29	
30	// ── Admin routes (lazy loaded) ────────────────────────────────
31	const AdminLayout = lazy(() =>
32	  import("@/components/AdminLayout").then((m) => ({ default: m.AdminLayout }))
33	);
34	const AdminDashboard = lazy(() => import("@/pages/admin/AdminDashboard"));
35	const AdminUsers = lazy(() => import("@/pages/admin/Users"));
36	const AdminUserDetail = lazy(() => import("@/pages/admin/UserDetail"));
37	const AdminAuditLog = lazy(() => import("@/pages/admin/AuditLog"));
38	const AdminScans = lazy(() => import("@/pages/admin/Scans"));
39	const AdminBilling = lazy(() => import("@/pages/admin/Billing"));
40	const AdminSystem = lazy(() => import("@/pages/admin/System"));
41	const AdminFeatureFlags = lazy(() => import("@/pages/admin/FeatureFlags"));
42	const AdminSupport = lazy(() => import("@/pages/admin/Support"));
43	
44	function AdminLoadingSpinner() {
45	  return (
46	    <div className="flex min-h-screen items-center justify-center bg-background">
47	      <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
48	    </div>
49	  );
50	}
51	
52	const queryClient = new QueryClient();
53	
54	const App = () => (
55	  <QueryClientProvider client={queryClient}>
56	    <TooltipProvider>
57	      <Toaster />
58	      <Sonner />
59	      <BrowserRouter>
60	        <AuthProvider>
61	          <Routes>
62	            {/* Public routes */}
63	            <Route path="/" element={<Landing />} />
64	            <Route path="/login" element={<Login />} />
65	            <Route path="/signup" element={<Signup />} />
66	            <Route path="/auth/callback" element={<AuthCallback />} />
67	            <Route path="/forgot-password" element={<ForgotPassword />} />
68	            <Route path="/reset-password" element={<ResetPassword />} />
69	            <Route path="/privacy" element={<Privacy />} />
70	            <Route path="/terms" element={<Terms />} />
71	            <Route path="/scan" element={<Scan />} />
72	
73	            {/* Protected app routes */}
74	            <Route element={<ProtectedRoute />}>
75	              <Route element={<AppLayout />}>
76	                <Route path="/dashboard" element={<Dashboard />} />
77	                <Route path="/reports" element={<Reports />} />
78	                <Route path="/reports/:id" element={<AuditReport />} />
79	                <Route path="/agents" element={<AgentHub />} />
80	                <Route path="/agents/:taskId" element={<AgentWorkspace />} />
81	                <Route path="/integrations" element={<Integrations />} />
82	                <Route path="/settings" element={<SettingsPage />} />
83	                <Route path="/pricing" element={<Pricing />} />
84	              </Route>
85	
86	              {/* Admin routes — nested inside ProtectedRoute, guarded by AdminRoute */}
87	              <Route element={<AdminRoute />}>
88	                <Route
89	                  path="/admin"
90	                  element={
91	                    <Suspense fallback={<AdminLoadingSpinner />}>
92	                      <AdminLayout />
93	                    </Suspense>
94	                  }
95	                >
96	                  <Route
97	                    index
98	                    element={
99	                      <Suspense fallback={<AdminLoadingSpinner />}>
100	                        <AdminDashboard />
101	                      </Suspense>
102	                    }
103	                  />
104	                  <Route
105	                    path="users"
106	                    element={
107	                      <Suspense fallback={<AdminLoadingSpinner />}>
108	                        <AdminUsers />
109	                      </Suspense>
110	                    }
111	                  />
112	                  <Route
113	                    path="users/:userId"
114	                    element={
115	                      <Suspense fallback={<AdminLoadingSpinner />}>
116	                        <AdminUserDetail />
117	                      </Suspense>
118	                    }
119	                  />
120	                  <Route
121	                    path="audit-log"
122	                    element={
123	                      <Suspense fallback={<AdminLoadingSpinner />}>
124	                        <AdminAuditLog />
125	                      </Suspense>
126	                    }
127	                  />
128	                  <Route
129	                    path="scans"
130	                    element={
131	                      <Suspense fallback={<AdminLoadingSpinner />}>
132	                        <AdminScans />
133	                      </Suspense>
134	                    }
135	                  />
136	                  <Route
137	                    path="billing"
138	                    element={
139	                      <Suspense fallback={<AdminLoadingSpinner />}>
140	                        <AdminBilling />
141	                      </Suspense>
142	                    }
143	                  />
144	                  <Route
145	                    path="system"
146	                    element={
147	                      <Suspense fallback={<AdminLoadingSpinner />}>
148	                        <AdminSystem />
149	                      </Suspense>
150	                    }
151	                  />
152	                  <Route
153	                    path="flags"
154	                    element={
155	                      <Suspense fallback={<AdminLoadingSpinner />}>
156	                        <AdminFeatureFlags />
157	                      </Suspense>
158	                    }
159	                  />
160	                  <Route
161	                    path="support"
162	                    element={
163	                      <Suspense fallback={<AdminLoadingSpinner />}>
164	                        <AdminSupport />
165	                      </Suspense>
166	                    }
167	                  />
168	                </Route>
169	              </Route>
170	            </Route>
171	
172	            <Route path="*" element={<NotFound />} />
173	          </Routes>
174	        </AuthProvider>
175	      </BrowserRouter>
176	    </TooltipProvider>
177	  </QueryClientProvider>
178	);
179	
180	export default App;
181

