1	/**
2	 * Supabase-generated-style database types for CROBOT.
3	 *
4	 * These types mirror the SQL schema in supabase/migrations/ and are fully
5	 * compatible with the app-level types in src/types/index.ts.
6	 *
7	 * Usage:
8	 *   import { createClient } from '@supabase/supabase-js'
9	 *   import type { Database } from '@/types/database'
10	 *
11	 *   const supabase = createClient<Database>(url, key)
12	 *   const { data } = await supabase.from('scans').select('*')
13	 *   // data is typed as Tables<'scans'>[]
14	 */
15	
16	import type { CroPillar, PageType, PlanType, ScanStatus, Severity, Effort, UserRole } from "./index";
17	
18	// ── Finding (JSONB shape stored inside scan_results.findings) ─
19	// Must stay in sync with the Finding interface in index.ts.
20	
21	export interface DbFinding {
22	  id: string;
23	  title: string;
24	  severity: Severity;
25	  current_state: string;
26	  recommendation: string;
27	  ai_suggestion: string;
28	  is_premium: boolean;
29	  effort: Effort;
30	  estimated_lift: string;
31	  category: string;
32	}
33	
34	// ── Table row shapes ──────────────────────────────────────────
35	
36	export interface ProfileRow {
37	  id: string;
38	  email: string;
39	  full_name: string;
40	  company_name: string | null;
41	  website_url: string | null;
42	  avatar_url: string | null;
43	  plan: PlanType;
44	  scans_used: number;
45	  scan_limit: number;
46	  role: UserRole;
47	  is_banned: boolean;
48	  stripe_customer_id: string | null;
49	  stripe_subscription_id: string | null;
50	  billing_cycle_end: string | null;
51	  created_at: string;
52	  updated_at: string;
53	}
54	
55	export interface AuditLogRow {
56	  id: string;
57	  admin_id: string;
58	  action: string;
59	  target_type: string | null;
60	  target_id: string | null;
61	  metadata: Record<string, unknown>;
62	  created_at: string;
63	}
64	
65	export type AuditLogInsert = Omit<AuditLogRow, "id" | "created_at">;
66	
67	export interface ScanRow {
68	  id: string;
69	  user_id: string;
70	  url: string;
71	  favicon_url: string | null;
72	  page_title: string | null;
73	  page_type: PageType;
74	  status: ScanStatus;
75	  overall_score: number | null;
76	  issues_found: number;
77	  critical_issues: number;
78	  warnings: number;
79	  quick_wins: number;
80	  screenshot_url: string | null;
81	  device: "desktop" | "mobile" | "both";
82	  error_message: string | null;
