97	
98	export interface IntegrationRow {
99	  id: string;
100	  user_id: string;
101	  provider: "hotjar" | "google_analytics" | "clarity" | "search_console";
102	  access_token: string | null;
103	  refresh_token: string | null;
104	  is_active: boolean;
105	  connected_at: string;
106	}
107	
108	// ── Insert types (required fields only, omit auto-generated) ──
109	
110	export type ProfileInsert = Pick<ProfileRow, "id" | "email"> &
111	  Partial<
112	    Omit<ProfileRow, "id" | "email" | "created_at" | "updated_at">
113	  >;
114	
115	export type ScanInsert = Pick<ScanRow, "user_id" | "url"> &
116	  Partial<Omit<ScanRow, "user_id" | "url" | "id" | "created_at">>;
117	
118	export type ScanResultInsert = Pick<
119	  ScanResultRow,
120	  "scan_id" | "pillar" | "score" | "weight"
121	> &
122	  Partial<Omit<ScanResultRow, "scan_id" | "pillar" | "score" | "weight" | "id" | "created_at">>;
123	
124	export type IntegrationInsert = Pick<
125	  IntegrationRow,
126	  "user_id" | "provider"
127	> &
128	  Partial<Omit<IntegrationRow, "user_id" | "provider" | "id" | "connected_at">>;
129	
130	// ── Update types (all fields optional except primary key) ─────
131	
132	export type ProfileUpdate = Partial<
133	  Omit<ProfileRow, "id" | "created_at">
134	>;
135	
136	export type ScanUpdate = Partial<Omit<ScanRow, "id" | "user_id" | "created_at">>;
137	
138	export type ScanResultUpdate = Partial<
139	  Omit<ScanResultRow, "id" | "scan_id" | "pillar" | "created_at">
140	>;
141	
142	export type IntegrationUpdate = Partial<
143	  Omit<IntegrationRow, "id" | "user_id" | "provider" | "connected_at">
144	>;
145	
146	// ── Supabase Database generic type ────────────────────────────
147	
148	export interface Database {
149	  public: {
150	    Tables: {
151	      profiles: {
152	        Row: ProfileRow;
153	        Insert: ProfileInsert;
154	        Update: ProfileUpdate;
155	      };
156	      scans: {
157	        Row: ScanRow;
158	        Insert: ScanInsert;
159	        Update: ScanUpdate;
160	      };
161	      scan_results: {
162	        Row: ScanResultRow;
163	        Insert: ScanResultInsert;
164	        Update: ScanResultUpdate;
165	      };
166	      integrations: {
167	        Row: IntegrationRow;
168	        Insert: IntegrationInsert;
169	        Update: IntegrationUpdate;
170	      };
171	      audit_logs: {
172	        Row: AuditLogRow;
173	        Insert: AuditLogInsert;
174	        Update: Partial<Omit<AuditLogRow, "id" | "created_at">>;
175	      };
176	    };
177	    Views: Record<string, never>;
178	    Functions: {
179	      increment_scan_usage: {
180	        Args: { user_uuid: string };
181	        Returns: boolean;
182	      };
183	      reset_monthly_scans: {
184	        Args: Record<string, never>;
185	        Returns: void;
186	      };
187	      is_admin: {
188	        Args: Record<string, never>;
189	        Returns: boolean;
190	      };
191	    };
192	    Enums: Record<string, never>;
193	  };
194	}
195	
196	// ── Convenience helpers ───────────────────────────────────────
197	// Use these for typed Supabase client access.
198	
199	export type Tables<T extends keyof Database["public"]["Tables"]> =
200	  Database["public"]["Tables"][T]["Row"];
201	
202	export type TablesInsert<T extends keyof Database["public"]["Tables"]> =
203	  Database["public"]["Tables"][T]["Insert"];
204	
205	export type TablesUpdate<T extends keyof Database["public"]["Tables"]> =
206	  Database["public"]["Tables"][T]["Update"];
207	
208	export type DbFunctions = Database["public"]["Functions"];
