147	              <span>Category: <span className="font-medium text-foreground">{finding.category}</span></span>
148	              <span>&middot;</span>
149	              <span>Effort: <span className="font-medium text-foreground">{getEffortLabel(finding.effort)}</span></span>
150	              {finding.estimated_lift && finding.estimated_lift !== "0%" && (
151	                <>
152	                  <span>&middot;</span>
153	                  <span>Expected lift: <span className="font-medium text-foreground">{finding.estimated_lift}</span></span>
154	                </>
155	              )}
156	            </div>
157	          </div>
158	        )}
159	      </CardContent>
160	    </Card>
161	  );
162	
163	  if (finding.is_premium) {
164	    return <PremiumLock>{content}</PremiumLock>;
165	  }
166	
167	  return content;
168	}
