1	import { useQuery } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	import { useAuth } from "@/contexts/AuthContext";
4	import type { DashboardStats, Scan, Finding } from "@/types";
5	import type { ScanRow, ScanResultRow, DbFinding } from "@/types/database";
6	
7	// ── Derived types for dashboard ─────────────────────────────────
8	
9	export interface ScoreTrendPoint {
10	  week: string;
11	  score: number;
12	}
13	
14	export interface ScoreDistributionBucket {
15	  range: string;
16	  count: number;
17	  fill: string;
18	}
19	
20	export interface DashboardData {
21	  stats: DashboardStats;
22	  recentScans: Scan[];
23	  scoreTrend: ScoreTrendPoint[];
24	  scoreDistribution: ScoreDistributionBucket[];
25	  topQuickWins: (Finding & { pillar: string })[];
26	  latestScanId: string | null;
27	}
28	
29	// ── Defaults (empty state) ──────────────────────────────────────
30	
31	const EMPTY_DASHBOARD: DashboardData = {
32	  stats: {
33	    total_scans: 0,
34	    avg_score: 0,
35	    total_issues: 0,
36	    critical_issues: 0,
37	    estimated_revenue_impact: 0,
38	    score_trend: 0,
39	    scans_trend: 0,
40	    quick_wins: 0,
41	  },
42	  recentScans: [],
43	  scoreTrend: [],
44	  scoreDistribution: [
45	    { range: "0-20", count: 0, fill: "#EF4444" },
46	    { range: "21-40", count: 0, fill: "#F87171" },
47	    { range: "41-60", count: 0, fill: "#F59E0B" },
48	    { range: "61-80", count: 0, fill: "#22C55E" },
49	    { range: "81-100", count: 0, fill: "#16A34A" },
50	  ],
51	  topQuickWins: [],
52	  latestScanId: null,
53	};
54	
55	// ── Helpers ─────────────────────────────────────────────────────
56	
57	function getWeekLabel(date: Date): string {
58	  const now = new Date();
59	  const diffMs = now.getTime() - date.getTime();
60	  const diffWeeks = Math.floor(diffMs / (1000 * 60 * 60 * 24 * 7));
61	  if (diffWeeks === 0) return "This week";
62	  if (diffWeeks === 1) return "1w ago";
63	  return `${diffWeeks}w ago`;
64	}
65	
66	function getBucketFill(range: string): string {
67	  const fills: Record<string, string> = {
68	    "0-20": "#EF4444",
69	    "21-40": "#F87171",
70	    "41-60": "#F59E0B",
71	    "61-80": "#22C55E",
72	    "81-100": "#16A34A",
73	  };
74	  return fills[range] ?? "#94A3B8";
75	}
76	
77	function scoreToRange(score: number): string {
78	  if (score <= 20) return "0-20";
79	  if (score <= 40) return "21-40";
80	  if (score <= 60) return "41-60";
81	  if (score <= 80) return "61-80";
82	  return "81-100";
83	}
84	
85	function rowToScan(row: ScanRow): Scan {
86	  return {
87	    id: row.id,
88	    user_id: row.user_id,
89	    url: row.url,
90	    favicon_url: row.favicon_url,
91	    page_title: row.page_title,
92	    page_type: row.page_type,
93	    status: row.status,
94	    overall_score: row.overall_score,
95	    issues_found: row.issues_found,
96	    critical_issues: row.critical_issues,
97	    warnings: row.warnings,
98	    quick_wins: row.quick_wins,
99	    screenshot_url: row.screenshot_url,
100	    device: row.device,
101	    created_at: row.created_at,
102	    completed_at: row.completed_at,
103	  };
104	}
105	
106	// ── useDashboardStats ───────────────────────────────────────────
107	
108	export function useDashboardStats() {
109	  const { user } = useAuth();
110	
111	  return useQuery({
112	    queryKey: ["dashboard-stats", user?.id ?? ""],
113	    queryFn: async (): Promise<DashboardData> => {
114	      if (!user?.id) return EMPTY_DASHBOARD;
115	
116	      // Fetch all completed scans for the user
117	      const { data: scansData, error: scansError } = await supabase
118	        .from("scans")
119	        .select("*")
120	        .eq("user_id", user.id)
121	        .order("created_at", { ascending: false });
122	
123	      if (scansError) throw new Error(scansError.message);
124	
125	      const scans = (scansData as ScanRow[]).map(rowToScan);
126	
127	      if (scans.length === 0) return EMPTY_DASHBOARD;
128	
129	      const completedScans = scans.filter((s) => s.status === "completed" && s.overall_score !== null);
130	      const recentScans = scans.slice(0, 5);
131	      const latestScanId = completedScans[0]?.id ?? null;
132	
133	      // ── Stats aggregation ─────────────────────────────────────
134	
135	      const now = new Date();
136	      const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
137	      const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
138	
139	      const scansThisMonth = completedScans.filter(
140	        (s) => new Date(s.created_at) >= monthStart
141	      );
142	      const scansLastMonth = completedScans.filter(
143	        (s) =>
144	          new Date(s.created_at) >= lastMonthStart &&
145	          new Date(s.created_at) < monthStart
146	      );
147	
148	      const avgScore =
149	        completedScans.length > 0
150	          ? Math.round(
151	              completedScans.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
152	                completedScans.length
153	            )
154	          : 0;
155	
156	      const avgScoreThisMonth =
157	        scansThisMonth.length > 0
158	          ? Math.round(
159	              scansThisMonth.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
160	                scansThisMonth.length
161	            )
162	          : 0;
163	
164	      const avgScoreLastMonth =
165	        scansLastMonth.length > 0
166	          ? Math.round(
167	              scansLastMonth.reduce((sum, s) => sum + (s.overall_score ?? 0), 0) /
168	                scansLastMonth.length
169	            )
170	          : 0;
171	
172	      const totalIssues = completedScans.reduce((sum, s) => sum + s.issues_found, 0);
173	      const totalCritical = completedScans.reduce((sum, s) => sum + s.critical_issues, 0);
174	      const totalQuickWins = completedScans.reduce((sum, s) => sum + s.quick_wins, 0);
175	
176	      const scoreTrendDelta =
177	        avgScoreLastMonth > 0 ? avgScoreThisMonth - avgScoreLastMonth : 0;
178	      const scansTrendDelta =
179	        scansLastMonth.length > 0
180	          ? Math.round(
181	              ((scansThisMonth.length - scansLastMonth.length) /
182	                scansLastMonth.length) *
183	                100
184	            )
185	          : scansThisMonth.length > 0
186	          ? 100
187	          : 0;
188	
189	      const stats: DashboardStats = {
190	        total_scans: scansThisMonth.length,
191	        avg_score: avgScore,
192	        total_issues: totalIssues,
193	        critical_issues: totalCritical,
194	        estimated_revenue_impact: Math.round(totalQuickWins * 125),
195	        score_trend: scoreTrendDelta,
196	        scans_trend: scansTrendDelta,
197	        quick_wins: totalQuickWins,
198	      };
199	
200	      // ── Score Trend (last 4 weeks) ────────────────────────────
201	
202	      const fourWeeksAgo = new Date(now.getTime() - 28 * 24 * 60 * 60 * 1000);
203	      const recentForTrend = completedScans.filter(
204	        (s) => new Date(s.created_at) >= fourWeeksAgo
205	      );
206	
207	      const weekBuckets = new Map<number, number[]>(); // weekIndex → scores[]
208	      for (const scan of recentForTrend) {
209	        const scanDate = new Date(scan.created_at);
210	        const diffMs = now.getTime() - scanDate.getTime();
211	        const weekIndex = 3 - Math.min(3, Math.floor(diffMs / (1000 * 60 * 60 * 24 * 7)));
212	        const existing = weekBuckets.get(weekIndex) ?? [];
213	        if (scan.overall_score !== null) {
214	          existing.push(scan.overall_score);
215	          weekBuckets.set(weekIndex, existing);
216	        }
217	      }
218	
219	      const WEEK_LABELS = ["3w ago", "2w ago", "1w ago", "This week"];
220	      const scoreTrend: ScoreTrendPoint[] = WEEK_LABELS.map((label, idx) => {
221	        const scores = weekBuckets.get(idx) ?? [];
222	        const avg =
223	          scores.length > 0
224	            ? Math.round(scores.reduce((s, v) => s + v, 0) / scores.length)
225	            : 0;
226	        return { week: label, score: avg };
227	      }).filter((p) => p.score > 0);
228	
229	      // ── Score Distribution ────────────────────────────────────
230	
231	      const RANGES = ["0-20", "21-40", "41-60", "61-80", "81-100"];
232	      const distributionMap = new Map<string, number>(RANGES.map((r) => [r, 0]));
233	
234	      for (const scan of completedScans) {
235	        if (scan.overall_score !== null) {
236	          const bucket = scoreToRange(scan.overall_score);
237	          distributionMap.set(bucket, (distributionMap.get(bucket) ?? 0) + 1);
238	        }
239	      }
240	
241	      const scoreDistribution: ScoreDistributionBucket[] = RANGES.map((range) => ({
242	        range,
243	        count: distributionMap.get(range) ?? 0,
244	        fill: getBucketFill(range),
245	      }));
246	
247	      // ── Top Quick Wins from latest completed scan ─────────────
248	
249	      let topQuickWins: (Finding & { pillar: string })[] = [];
250	
251	      if (latestScanId) {
252	        const { data: resultsData } = await supabase
253	          .from("scan_results")
254	          .select("*")
255	          .eq("scan_id", latestScanId);
256	
257	        if (resultsData && resultsData.length > 0) {
258	          const allFindings: (Finding & { pillar: string })[] = (
259	            resultsData as ScanResultRow[]
260	          ).flatMap((r) =>
261	            (r.findings ?? [])
262	              .filter((f: DbFinding) => f.severity !== "passed" && f.effort === "quick")
263	              .map((f: DbFinding) => ({
264	                id: f.id,
265	                title: f.title,
266	                severity: f.severity,
267	                current_state: f.current_state,
268	                recommendation: f.recommendation,
269	                ai_suggestion: f.ai_suggestion,
270	                is_premium: f.is_premium,
271	                effort: f.effort,
272	                estimated_lift: f.estimated_lift,
273	                category: f.category,
274	                pillar: r.pillar,
275	              }))
276	          );
277	
278	          topQuickWins = allFindings
279	            .sort((a, b) => {
280	              const liftA = parseFloat(a.estimated_lift.match(/[\d.]+/)?.[0] ?? "0");
281	              const liftB = parseFloat(b.estimated_lift.match(/[\d.]+/)?.[0] ?? "0");
282	              return liftB - liftA;
283	            })
284	            .slice(0, 3);
285	        }
286	      }
287	
288	      return {
289	        stats,
290	        recentScans,
291	        scoreTrend,
292	        scoreDistribution,
293	        topQuickWins,
294	        latestScanId,
295	      };
296	    },
297	    enabled: !!user?.id,
298	    staleTime: 1000 * 60 * 2, // 2 minutes
299	  });
300	}
