112	// ── Copy Button ─────────────────────────────────────────────────
113	
114	function CopyButton({ text }: { text: string }) {
115	  const [copied, setCopied] = useState(false);
116	
117	  const handleCopy = async () => {
118	    try {
119	      await navigator.clipboard.writeText(text);
120	      setCopied(true);
121	      setTimeout(() => setCopied(false), 2000);
122	    } catch {
123	      const textarea = document.createElement("textarea");
124	      textarea.value = text;
125	      document.body.appendChild(textarea);
126	      textarea.select();
127	      document.execCommand("copy");
128	      document.body.removeChild(textarea);
129	      setCopied(true);
130	      setTimeout(() => setCopied(false), 2000);
131	    }
132	  };
133	
134	  return (
135	    <TooltipProvider delayDuration={200}>
136	      <Tooltip>
137	        <TooltipTrigger asChild>
138	          <button
139	            onClick={handleCopy}
140	            className={cn(
141	              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all",
142	              copied
143	                ? "bg-green-50 text-green-600 border border-green-200"
144	                : "bg-white/80 text-slate-500 border border-border/50 hover:bg-muted/40 hover:text-foreground"
145	            )}
146	          >
147	            {copied ? (
148	              <><Check className="h-3 w-3" />Copied</>
149	            ) : (
150	              <><Copy className="h-3 w-3" />Copy</>
151	            )}
152	          </button>
153	        </TooltipTrigger>
154	        <TooltipContent side="top">
155	          <p>{copied ? "Copied to clipboard!" : "Copy AI suggestion"}</p>
156	        </TooltipContent>
157	      </Tooltip>
158	    </TooltipProvider>
159	  );
160	}
